// Writes src/data/storyAudio.js — a static require() map of every bundled
// narration file. Metro can only bundle assets referenced by literal
// require() calls, so this file is generated from what's on disk.
//
// File naming: assets/audio/<filmId>-<ageRange>.<m4a|mp3>  (m4a preferred)

const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..", "..");
const AUDIO_DIR = path.join(ROOT, "assets", "audio");
const OUT_PATH = path.join(ROOT, "src", "data", "storyAudio.js");
const NAME_RE = /^(.+)-(3-5|6-8|9-12)\.(m4a|mp3)$/;

function writeAudioManifest() {
  const files = fs.existsSync(AUDIO_DIR) ? fs.readdirSync(AUDIO_DIR).sort() : [];
  const map = {};
  for (const file of files) {
    const m = file.match(NAME_RE);
    if (!m) continue;
    const [, filmId, age, ext] = m;
    // Prefer the optimised .m4a when both exist.
    if (map[filmId]?.[age] && ext === "mp3") continue;
    map[filmId] = { ...(map[filmId] || {}), [age]: file };
  }

  const lines = [
    "// Auto-generated by scripts/lib/audio-manifest.js — do not edit manually.",
    "// Regenerate with: node scripts/generate-stories.js (or scripts/optimize-audio.js)",
    "export const STORY_AUDIO = {",
  ];
  for (const filmId of Object.keys(map).sort()) {
    const entries = Object.entries(map[filmId])
      .map(([age, file]) => `"${age}": require("../../assets/audio/${file}")`)
      .join(", ");
    lines.push(`  ${JSON.stringify(filmId)}: { ${entries} },`);
  }
  lines.push("};", "");
  fs.writeFileSync(OUT_PATH, lines.join("\n"));
  return map;
}

module.exports = { writeAudioManifest };

if (require.main === module) {
  const map = writeAudioManifest();
  console.log(`Wrote src/data/storyAudio.js (${Object.keys(map).length} films)`);
}
